import{_ as r,c as i,j as n,a as t,G as s,a2 as o,B as d,o as h}from"./chunks/framework.rHWNTPhC.js";const b=JSON.parse('{"title":"Keine Verwendung von i18n von Beginn an","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-no-use-of-i18n-at-start.md","filePath":"technik/adr/adr-no-use-of-i18n-at-start.md"}'),l={name:"technik/adr/adr-no-use-of-i18n-at-start.md"};function u(c,e,p,g,f,m){const a=d("adr-status");return h(),i("div",null,[e[0]||(e[0]=n("h1",{id:"keine-verwendung-von-i18n-von-beginn-an",tabindex:"-1"},[t("Keine Verwendung von i18n von Beginn an "),n("a",{class:"header-anchor",href:"#keine-verwendung-von-i18n-von-beginn-an","aria-label":'Permalink to "Keine Verwendung von i18n von Beginn an"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[t("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),s(a,{status:"accepted"}),e[2]||(e[2]=o('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Analog zur RefArch-<a href="https://github.com/it-at-m/refarch-templates/issues/116" target="_blank" rel="noreferrer">Diskussion</a> haben wir im Projekt überlegt, ob wir i18n einsetzen werden.</p><p>Bibliotheken wie <a href="https://vue-i18n.intlify.dev/" target="_blank" rel="noreferrer">vue-i18n</a> erlauben es auf einfache Weise zwischen Sprachen zu wechseln. Dies umfasst sowohl Texte als auch die Formatierung von Zahlen und Daten. In dem die Texte in Ressourcen-Dateien gebündelt werden und in den Komponenten über Schlüssel auf die entsprechende Texte referenziert wird, können dieselben Texte leicht wiederverwendet werden.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Wir haben uns dagegen entschieden, i18n in der aktuellen Phase einzusetzen. WLS ist für den Münchner Prozess zur Auszählung der Stimmen. Wir gehen aktuell nicht davon aus der Nutzerkreis der Software eine Mehrsprachigkeit erfordert.</p><p>Eine spätere Verwendung von i18n hat keinen relevanten erhöhten Aufwand als wenn wir es von Beginn an verwenden würden. Alle erstellten Komponenten müssten analysiert und die Texte extrahiert und durch Referenzen ersetzt werden.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><h3 id="positiv" tabindex="-1">positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;positiv&quot;">​</a></h3><p>Die Texte sind direkt in den Komponenten erkennbar was die Verständlichkeit der Komponenten und der Fachdomain erleichtert. Es gibt eine Bibliothek weniger, von der wir abhängig sind und die zu Pflegen ist, was die Komplexität geringer hält.</p><h3 id="negativ" tabindex="-1">negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;negativ&quot;">​</a></h3><p>Dieselben Texte, vermutlich einzelne Wörter, lassen sich schwer über mehrere Komponenten hinweg identisch halten.</p><p>Wir müssen eigenen Formatierungsfunktionen für Zahlen und Daten erstellen.</p>',12))])}const k=r(l,[["render",u]]);export{b as __pageData,k as default};
